function getBenefitTitle(t: TranslationFn, id: BenefitId) {
  switch (id) {
    case "marketEconomics":
      return t("permissionlessListing.info.benefit.marketEconomics.title");
    case "noBottleneck":
      return t("permissionlessListing.info.benefit.noBottleneck.title");
    case "configuration":
      return t("permissionlessListing.info.benefit.configuration.title");
    case "isolation":
      return t("permissionlessListing.info.benefit.isolation.title");
  }
}

function getBenefitDescription(t: TranslationFn, id: BenefitId) {
  switch (id) {
    case "marketEconomics":
      return t(
        "permissionlessListing.info.benefit.marketEconomics.description"
      );
    case "noBottleneck":
      return t("permissionlessListing.info.benefit.noBottleneck.description");
    case "configuration":
      return t("permissionlessListing.info.benefit.configuration.description");
    case "isolation":
      return t("permissionlessListing.info.benefit.isolation.description");
  }
}

function getStepTitle(t: TranslationFn, id: StepId) {
  switch (id) {
    case "eligible":
      return t("permissionlessListing.info.step.eligible.title");
    case "configure":
      return t("permissionlessListing.info.step.configure.title");
    case "launchTime":
      return t("permissionlessListing.info.step.launchTime.title");
    case "activate":
      return t("permissionlessListing.info.step.activate.title");
  }
}

function getStepDescription(t: TranslationFn, id: StepId) {
  switch (id) {
    case "eligible":
      return t("permissionlessListing.info.step.eligible.description");
    case "configure":
      return t("permissionlessListing.info.step.configure.description");
    case "launchTime":
      return t("permissionlessListing.info.step.launchTime.description");
    case "activate":
      return t("permissionlessListing.info.step.activate.description");
  }
}

function getStepActivation(t: TranslationFn, id: StepId) {
  return id === "activate"
    ? t("permissionlessListing.info.step.activate.activation")
    : null;
}

function getStepNote(t: TranslationFn, id: StepId) {
  return id === "activate"
    ? t("permissionlessListing.info.step.activate.note")
    : null;
}

function getDetailQuestion(t: TranslationFn, id: DetailId) {
  switch (id) {
    case "insuranceFund":
      return t("permissionlessListing.info.detail.insuranceFund.question");
    case "insuranceFundFee":
      return t("permissionlessListing.info.detail.insuranceFundFee.question");
    case "fundInsurance":
      return t("permissionlessListing.info.detail.fundInsurance.question");
    case "customOracle":
      return t("permissionlessListing.info.detail.customOracle.question");
    case "risk":
      return t("permissionlessListing.info.detail.risk.question");
    case "orderlyOperating":
      return t("permissionlessListing.info.detail.orderlyOperating.question");
  }
}

function getDetailAnswer(t: TranslationFn, id: DetailId) {
  switch (id) {
    case "insuranceFund":
      return t("permissionlessListing.info.detail.insuranceFund.answer");
    case "insuranceFundFee":
      return t("permissionlessListing.info.detail.insuranceFundFee.answer");
    case "fundInsurance":
      return t("permissionlessListing.info.detail.fundInsurance.answer");
    case "customOracle":
      return t("permissionlessListing.info.detail.customOracle.answer");
    case "risk":
      return t("permissionlessListing.info.detail.risk.answer");
    case "orderlyOperating":
      return t("permissionlessListing.info.detail.orderlyOperating.answer");
  }
}

function getDetailLinkLabel(t: TranslationFn, id: DetailId) {
  switch (id) {
    case "fundInsurance":
      return t("permissionlessListing.info.detail.fundInsurance.linkLabel");
    case "customOracle":
      return t("permissionlessListing.info.detail.customOracle.linkLabel");
    default:
      return null;
  }
}

function SectionLabel({ children }: { children: React.ReactNode }) {
  return (
    <div className="text-xs font-semibold uppercase tracking-[1.8px] text-(--fg-brand)">
      {children}
    </div>
  );
}

